/* Generated by Trae Work */
/* 进度游标引擎：每门课一个「学到哪了」指针，今日计划从指针顺延生成，完成/跳过自动前进；
   任务量按考期自动倒排（剩余单元 ÷ 剩余天数），主线课优先推进、支线每天各 1 个小任务。
   存储键：course_cursor{code:已完成单元数}、main_course、skipped_units{code:[已跳过序号]} */
"use strict";
(function () {
  /* ---------- 单元序列 ---------- */
  const MATH2_SUBS = ["一元函数微分学", "一元函数积分学", "多元函数微积分（大纲范围内）", "常微分方程", "行列式与矩阵", "向量组与线性方程组", "特征值与二次型"];
  const ENG2_SUBS = ["完形填空（20 题 × 0.5 分）", "传统阅读 4 篇（20 题 × 2 分）", "新题型（5 题 × 2 分）", "翻译（约 150 词段落，15 分）", "写作（15 分）"];

  function zkChaptersOf(code) {
    const c = SITE_DATA.zikao.courses.find(x => x.code === code);
    if (!c) return null;
    const chapters = c.has_syllabus && c.chapters ? c.chapters : (c.reference_chapters ? c.reference_chapters.chapters : null);
    if (!chapters || !chapters.length) return null;
    return { c, chapters };
  }
  /* 返回该课的单元序列：[{idx, code, track, subject, title, source_url, source_basis}] */
  function unitsOf(code) {
    if (code === "数二") {
      return MATH2_SUBS.map((t, i) => ({
        idx: i, code, track: "kaoyan", subject: "数二", title: t,
        source_url: (SITE_DATA.kaoyan.math2 || {}).source_url || "", source_basis: "outline_section"
      }));
    }
    if (code === "英二") {
      return ENG2_SUBS.map((t, i) => ({
        idx: i, code, track: "kaoyan", subject: "英二", title: t,
        source_url: (SITE_DATA.kaoyan.eng2 || {}).source_url || "", source_basis: "outline_section"
      }));
    }
    if (code === "408") {
      const arr = [];
      SITE_DATA.kaoyan.exam408.subjects.forEach(sub => {
        sub.chapters.forEach(ch => {
          arr.push({
            idx: arr.length, code: "408", track: "kaoyan", subject: sub.code,
            title: `${sub.name}：${ch.title}`, subName: sub.name,
            source_url: SITE_DATA.kaoyan.exam408.syllabus_source.source_url, source_basis: "outline_section"
          });
        });
      });
      return arr;
    }
    const zk = zkChaptersOf(code);
    if (!zk) return [];
    return zk.chapters.map((t, i) => ({
      idx: i, code: zk.c.code, track: "zikao", subject: zk.c.code, title: t,
      source_url: zk.c.has_syllabus ? zk.c.syllabus_url : zk.c.reference_chapters.source_url,
      source_basis: zk.c.has_syllabus ? "syllabus_chapter" : "reference_chapter"
    }));
  }
  function unitsTotal(code) { return unitsOf(code).length; }

  /* ---------- 游标存取 ---------- */
  function cursorMap() { return Store.get("course_cursor", {}); }
  function cursorOf(code) {
    const total = unitsTotal(code);
    return Math.max(0, Math.min(cursorMap()[code] || 0, total));
  }
  function setCursor(code, doneCount) {
    const m = cursorMap();
    m[code] = Math.max(0, Math.min(doneCount, unitsTotal(code)));
    Store.set("course_cursor", m);
    /* 推进历史：每天每课记录一次最终位置（看板游标折线数据源） */
    const h = Store.get("cursor_history", {});
    const t = fmtDate(new Date());
    h[t] = h[t] || {};
    h[t][code] = m[code];
    Store.set("cursor_history", h);
    /* 校准游标时清掉该课旧单元的完成/跳过覆盖，避免历史状态误标 */
    const ov = Store.get("block_overrides", {});
    const re = new RegExp("^u-" + code.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "-\\d+$");
    Object.keys(ov).forEach(k => { if (re.test(k)) delete ov[k]; });
    Store.set("block_overrides", ov);
  }
  function markUnitDone(code, idx) {
    if (idx + 1 > cursorOf(code)) setCursor(code, idx + 1);
  }
  function skippedMap() { return Store.get("skipped_units", {}); }
  function skipUnit(code, idx) {
    const m = skippedMap();
    const arr = m[code] || [];
    if (!arr.includes(idx)) { arr.push(idx); m[code] = arr; Store.set("skipped_units", m); }
    markUnitDone(code, idx);
  }
  function isUnitId(id) { return /^u-.+-\d+$/.test(id); }
  function parseUnitId(id) {
    const m = /^u-(.+)-(\d+)$/.exec(id);
    return m ? { code: m[1], idx: +m[2] } : null;
  }

  /* ---------- 游标状态跨设备同步 ---------- */
  function cursorState() {
    return { course_cursor: cursorMap(), main_course: Store.get("main_course", ""), skipped_units: skippedMap() };
  }
  /* 采用云端游标：只进不退（云端进度更多才采纳），返回是否发生变化 */
  function applyCursorState(st) {
    if (!st || !st.course_cursor) return false;
    let changed = false;
    const m = cursorMap();
    Object.entries(st.course_cursor).forEach(([code, v]) => {
      const total = unitsTotal(code);
      const c = Math.max(0, Math.min(+v || 0, total));
      if (total > 0 && c > (m[code] || 0)) { m[code] = c; changed = true; }
    });
    if (changed) {
      Store.set("course_cursor", m);
      const h = Store.get("cursor_history", {});
      const t = fmtDate(new Date());
      h[t] = h[t] || {};
      Object.entries(m).forEach(([code, v]) => { h[t][code] = v; });
      Store.set("cursor_history", h);
    }
    return changed;
  }

  /* ---------- 主线课 ---------- */
  function coursePool() {
    const zk = Store.get("zk_subjects", []);
    const ky = Store.get("ky_subjects", ["数二", "英二", "408"]);
    return zk.concat(ky).filter(c => unitsTotal(c) > 0);
  }
  function mainCourse() {
    const m = Store.get("main_course", "");
    const pool = coursePool();
    return pool.includes(m) ? m : (pool[0] || "");
  }
  function setMainCourse(code) {
    if (coursePool().includes(code)) Store.set("main_course", code);
  }

  /* ---------- 考期 ---------- */
  function secondSaturdayOf(year, month) { /* 该月第 2 个周六 */
    const d = new Date(year, month - 1, 1);
    d.setDate(1 + ((6 - d.getDay() + 7) % 7) + 7);
    return fmtDate(d);
  }
  function lastSaturdayOf(year, month) { /* 该月最后一个周六 */
    const d = new Date(year, month, 0); /* 月末 */
    d.setDate(d.getDate() - ((d.getDay() + 1) % 7));
    return fmtDate(d);
  }
  /* 官方未公布时按往年惯例推算：4 月第 2 个周六、10 月最后一个周六，取今天之后最近者 */
  function estimatedZikaoDate() {
    const now = new Date();
    const cands = [];
    [now.getFullYear(), now.getFullYear() + 1].forEach(y => {
      cands.push(secondSaturdayOf(y, 4), lastSaturdayOf(y, 10));
    });
    const today = fmtDate(now);
    const future = cands.filter(d => d >= today).sort();
    return future[0] || null;
  }
  function zikaoExamDate() {
    try {
      const ev = nextZikaoDate();
      if (ev && ev.date_start) return { date: ev.date_start, confirmed: true };
    } catch (e) { /* 数据缺失时走推算 */ }
    const est = estimatedZikaoDate();
    return est ? { date: est, confirmed: false } : null;
  }
  /* 每门课的考试日期与剩余天数（主线/支线统一口径：自考课看自考考期，考研课看考研日期） */
  function examDateOf(code) {
    if (["数二", "英二", "408"].includes(code)) return { date: SITE_DATA.countdown.kaoyan_target, confirmed: true };
    const zk = zikaoExamDate();
    return zk ? { date: zk.date, confirmed: zk.confirmed } : null;
  }
  function daysUntilExam(code) {
    const e = examDateOf(code);
    if (!e) return null;
    return Math.max(1, daysUntil(e.date));
  }

  /* ---------- 每日任务量（自动倒排） ---------- */
  function quotaFor(code, isMain, offsetDays) {
    const total = unitsTotal(code);
    const done = cursorOf(code);
    const remaining = total - done;
    if (remaining <= 0) return 0;
    const daysLeft = Math.max(1, (daysUntilExam(code) || 30) - (offsetDays || 0));
    return Math.max(1, Math.min(3, Math.ceil(remaining / daysLeft)));
  }
  function todayQuota() {
    const pool = coursePool();
    const main = mainCourse();
    return {
      main, mainQuota: main ? quotaFor(main, true) : 0,
      sides: pool.filter(c => c !== main).map(c => ({ code: c, quota: 1 }))
    };
  }

  /* ---------- 考前完成率预测 ---------- */
  function forecast(code) {
    const total = unitsTotal(code);
    const done = cursorOf(code);
    const remaining = total - done;
    const isMain = code === mainCourse();
    const q = isMain ? Math.max(1, quotaFor(code, true)) : 1;
    const daysLeft = daysUntilExam(code);
    if (!daysLeft || remaining <= 0) {
      return { total, done, remaining, percentByExam: remaining <= 0 ? 100 : null, finishDate: remaining <= 0 ? fmtDate(new Date()) : null, onTrack: remaining <= 0 };
    }
    const daysNeed = Math.ceil(remaining / q);
    const finish = new Date(); finish.setHours(0, 0, 0, 0); finish.setDate(finish.getDate() + daysNeed);
    const byExam = Math.min(total, done + daysLeft * q);
    return {
      total, done, remaining,
      percentByExam: Math.round(byExam / total * 100),
      finishDate: fmtDate(finish),
      onTrack: daysNeed <= daysLeft
    };
  }

  /* ---------- 今日任务块（与旧课表块同构，兼容快照协议与打卡统计） ---------- */
  function unitBlock(u, role, dateISO) {
    const dur = role === "main" ? 90 : 45;
    const title = u.title; /* 408 已含「子科：章节」；其余课名由展示层用 poolLabel 拼接 */
    return {
      id: `u-${u.code}-${u.idx}`,
      date: dateISO || fmtDate(new Date()), track: u.track, subject: u.code,
      content_title: `${title}${role === "main" ? "（主线）" : "（支线）"}`,
      source_basis: u.source_basis, source_url: u.source_url,
      duration_min: dur, time_slot: role === "main" ? "morning" : "afternoon",
      _role: role, status: "pending"
    };
  }
  function poolLabel(code) {
    if (code === "数二") return "数学（二）";
    if (code === "英二") return "英语（二）";
    if (code === "408") return "408 计算机学科专业基础综合";
    const c = SITE_DATA.zikao.courses.find(x => x.code === code);
    return c ? `${c.code} ${c.name}` : code;
  }
  /* 今日全部游标任务块：主线 N 个 + 各支线 1 个；
     排序为紧迫度优先：考前完成率低的课排最前（最危险先学），并列时主线课优先 */
  /* 某天的游标任务块（offset=0 即今天；预排只读不落库，完成状态仍以实际打卡为准） */
  function unitBlocksFor(offsetDays) {
    const plan = todayQuota();
    if (!plan.main) return [];
    const dateISO = fmtDate(new Date(new Date().getTime() + (offsetDays || 0) * 86400000));
    const groups = [];
    const pushCourse = (code, role, n) => {
      const units = unitsOf(code);
      const cur = cursorOf(code);
      const remaining = units.length - cur;
      if (remaining <= 0) return; /* 已完成的课不再出新卡片，完成状态在进度条上以 100% 绿色标明 */
      const blocks = [];
      for (let i = 0; i < Math.min(n, remaining); i++) blocks.push(unitBlock(units[cur + i], role, dateISO));
      const f = forecast(code);
      groups.push({ code, blocks, key: f.percentByExam === null ? 101 : f.percentByExam });
    };
    const mq = quotaFor(plan.main, true, offsetDays || 0);
    if (mq > 0) pushCourse(plan.main, "main", mq);
    plan.sides.forEach(s => pushCourse(s.code, "side", 1));
    groups.sort((a, b) => a.key - b.key || (a.code === plan.main ? -1 : b.code === plan.main ? 1 : 0));
    const out = [];
    groups.forEach(g => out.push(...g.blocks));
    return out;
  }
  function todayUnitBlocks() { return unitBlocksFor(0); }

  window.CursorAPI = {
    unitsOf, unitsTotal, cursorOf, setCursor, markUnitDone, skipUnit,
    isUnitId, parseUnitId, coursePool, mainCourse, setMainCourse,
    examDateOf, daysUntilExam, todayQuota, forecast, todayUnitBlocks, poolLabel,
    unitBlocksFor, cursorState, applyCursorState
  };
})();
